Android (Java)iOS (Objective-C)Flutter (Dart) <pre><code>import com.axsecurity.sdk.service.AXService;
import com.axsecurity.sdk.base.AXConfig;

public class MyApplication extends Application {
    @Override
    public void onCreate() {
        super.onCreate();

        AXConfig config = new AXConfig.Builder()
            .accessKey("YOUR_ACCESS_KEY_ID", "YOUR_ACCESS_KEY_SECRET")
            .edgeNodes(new String[] { "doh.example.com", "203.0.113.1" })
            .build();

        int ret = AXService.initialize(this.getApplicationContext(), config);
        if (ret != 0) {
            Log.e("AXService", "init failed: " + ret);
        }
    }
}
</code></pre> <pre><code>#import &lt;AXSecurity/axsecurity.h&gt;

- (BOOL)application:(UIApplication *)application
    didFinishLaunchingWithOptions:(NSDictionary *)options {
    AXConfig *config = [[AXConfig alloc] init];
    config.accessKeyID     = @"YOUR_ACCESS_KEY_ID";
    config.accessKeySecret = @"YOUR_ACCESS_KEY_SECRET";
    config.edgeNodes       = @[@"doh.example.com", @"203.0.113.1"];

    int ret = [AXService initialize:config];
    if (ret != 0) {
        NSLog(@"AXService init failed: %d", ret);
    }
    return YES;
}
</code></pre> <pre><code>import 'package:axsecurity_flutter_plugin/axsecurity_flutter_plugin.dart';
import 'package:axsecurity_flutter_plugin/config.dart';

Future&lt;void&gt; main() async {
  WidgetsFlutterBinding.ensureInitialized();

  final cfg = AxConfig(
    accessKeyId: 'YOUR_ACCESS_KEY_ID',
    accessKeySecret: 'YOUR_ACCESS_KEY_SECRET',
    edgeNodes: ['doh.example.com', '203.0.113.1'],
  );

  final ret = await AxService.initialize(config: cfg);
  if (ret != 0) {
    debugPrint('AxService init failed: $ret');
  }
  runApp(const MyApp());
}
</code></pre>

问题 原因 解决方案 初始化崩溃 缺少 <code>INTERNET</code> 或 <code>ACCESS_NETWORK_STATE</code> 权限 在 <code>AndroidManifest.xml</code> 中添加权限声明 ProGuard 混淆后异常 SDK 类被混淆 添加 ProGuard 规则保留 <code>com.axsecurity.**</code> 多进程重复初始化 <code>Application.onCreate</code> 在每个进程都执行 判断当前进程，仅在主进程初始化 AAR 找不到 依赖配置不正确 确认 <code>libs/</code> 目录下有 <code>.aar</code> 文件，<code>build.gradle</code> 包含 <code>fileTree</code> 依赖 <p>ProGuard 规则示例： <pre><code>-keep class com.axsecurity.** { *; }
-dontwarn com.axsecurity.**
</code></pre></p>
